/// Builds the trust-anchor store holding only root A.
///
/// Root B is intentionally absent so an unknown-issuer certificate cannot
/// verify by accident.
#[must_use]
pub fn root_store_a() -> rustls::RootCertStore {
    let mut roots = rustls::RootCertStore::empty();
    roots
        .add(rustls::pki_types::CertificateDer::from(CA_A))
        .expect("synthetic root A parses as a trust anchor");
    roots
}

/// Builds the trust-anchor store holding only root B.
///
/// Used to prove the unknown-issuer case is really about the anchor set and not
/// about an unparseable certificate.
#[must_use]
pub fn root_store_b() -> rustls::RootCertStore {
    let mut roots = rustls::RootCertStore::empty();
    roots
        .add(rustls::pki_types::CertificateDer::from(CA_B))
        .expect("synthetic root B parses as a trust anchor");
    roots
}

